itle", this, new Func<IPlayer, string>(getFormattedClanTag)); }  void OnPluginLoaded(Plugin plugin) { if (plugin.Title != "Better Chat") return; if (enableClanTagging) Interface.CallHook("API_RegisterThirdPartyTitle", this, new Func<IPlayer, string>(getFormattedClanTag)); }  string getFormattedClanTag(IPlayer player) { var clan = findClanByUser(player.Id); if (clan != null && !string.IsNullOrEmpty(clan.tag)) return $"[#{clanTagColorBetterChat.Replace("#","")}][+{clanTagSizeBetterChat}]{clanTagOpening}{clan.tag}{clanTagClosing}[/+][/#]"; return string.Empty; }  void OnServerInitialized() { if (enableRustIOSupport) ioInitialize(); LoadData(); if (purgeOldClans) Puts($"Valid clans loaded: '{clans.Count}'"); if (purgeOldClans && purgedClans.Count() > 0) { Puts($"Old Clans purged: '{purgedClans.Count}'"); if (listPurgedClans) { foreach (var purged in purgedClans) Puts($"Purged > {purged}"); } } AllyRemovalCheck(); tagReExt = new Regex("[^a-zA-Z0-9" + allowedSpecialChars + "]"); foreach (var player in BasePlayer.activePlayerList) setupPlayer(player); foreach (var player in BasePlayer.sleepingPlayerList) setupPlayer(player); Initialized = true; }  void OnServerSave() { SaveData(); }  void OnNewSave() { if (wipeClansOnNewSave) newSaveDetected = true; }  void Unload() { if (!Initialized) return; SaveData(); foreach (var pair in originalNames) { var player = rust.FindPlayerByIdString(pair.Key); if (player != null && player.displayName != pair.Value) { displayName.SetValue(player, pair.Value); if (player.net != null) name.SetValue(player, string.Format("{1}[{0}/{2}]", player.net.ID, pair.Value, player.userID)); player.SendNetworkUpdate(); } } }  void ioInitialize() { lib = Interface.GetMod().GetLibrary<Library>("RustIO"); if (lib == null || (isInstalled = lib.GetFunction("IsInstalled")) == null || (addFriend = lib.GetFunction("AddFriend")) == null) { lib = null; Puts("{0}: {1}", Title, "Rust:IO is not present. You need to install Rust:IO first in order to use this plugin!"); } }  bool ioIsInstalled() { if (lib == null) return false; return (bool)isInstalled.Invoke(lib, new object[] { }); }  bool ioAddFriend(string playerId, string friendId) { if (lib == null) return false; return (bool)addFriend.Invoke(lib, new object[] { playerId, friendId }); }  void LoadData() { if (wipeClansOnNewSave && newSaveDetected) { var newdata = Interface.GetMod().DataFileSystem.GetDatafile("rustio_clans"); newdata.Save(Interface.GetMod().DataFileSystem.Directory+ "/rustio_clans.old"); clans.Clear(); newdata["clans"] = clans; Interface.GetMod().DataFileSystem.SaveDatafile("rustio_clans"); Puts("New save detected > Created backup of clans and wiped datafile."); return; } Puts("Loading clans data."); clans.Clear(); var data = Interface.GetMod().DataFileSystem.GetDatafile("rustio_clans"); if (data["clans"] != null) { Dictionary<string, object> clansData = new Dictionary<string, object>(); try { clansData = (Dictionary<string, object>)Convert.ChangeType(data["clans"], typeof(Dictionary<string, object>)); } catch { } foreach (var iclan in clansData) { string tag = iclan.Key; string permGroup = permGroupPrefix + tag; if (usePermGroups && !permission.GroupExists(permGroup)) permission.CreateGroup(permGroup, "Clan " + tag, 0); var clanData = iclan.Value as Dictionary<string, object>; string description = (string)clanData["description"]; string owner = (string)clanData["owner"];  string council = null; if (clanData.ContainsKey("council")) council = (string)clanData["council"]; if (!enableClanAllies) council = null; List<string> moderators = new List<string>(); foreach (var imoderator in clanData["moderators"] as List<object>) { moderators.Add((string)imoderator); } List<string> members = new List<string>(); foreach (var imember in clanData["members"] as List<object>) { members.Add((string)imember); if (usePermGroups && !permission.UserHasGroup((string)imember, permGroup)) permission.AddUserGroup((string)imember, permGroup); } List<string> clanAlliances = new List<strin