 { offline = true; break; } } if (offline) { sb.Append(string.Format(msg("memberoff", player.UserIDString))); n = 0; foreach (var memberId in Clan.members) { var p = this.covalence.Players.FindPlayer(memberId); if (p != null && !p.IsConnected) { if (n > 0) sb.Append(", "); if (Clan.IsOwner(memberId)) { sb.Append(string.Format(msg("overviewnamecolor", player.UserIDString), clanOwnerColor, p.Name)); } else if (Clan.IsCouncil(memberId)) { sb.Append(string.Format(msg("overviewnamecolor", player.UserIDString), clanCouncilColor, p.Name)); } else if (Clan.IsModerator(memberId)) { sb.Append(string.Format(msg("overviewnamecolor", player.UserIDString), clanModeratorColor, p.Name)); } else { sb.Append(string.Format(msg("overviewnamecolor", player.UserIDString), clanMemberColor, p.Name)); } ++n; } } sb.Append("\n"); } sb.AppendLine($"Time created: <color={colorClanNamesOverview}>{UnixTimeStampToDateTime(Clan.created)}</color>"); sb.AppendLine($"Last change: <color={colorClanNamesOverview}>{UnixTimeStampToDateTime(Clan.updated)}</color>"); SendReply(player, sb.ToString().TrimEnd()); }  void cmdChatClanchat(BasePlayer player, string command, string[] args) { if (player == null || args.Length == 0) return; var myClan = findClanByUser(player.UserIDString); if (myClan == null) { SendReply(player, string.Format(msg("notmember", player.UserIDString))); return; } var message = string.Join(" ", args); if (string.IsNullOrEmpty(message)) return; myClan.BroadcastChat(string.Format(msg("broadcastformat"), myClan.PlayerColor(player.UserIDString), player.net.connection.username, message)); if (ConVar.Chat.serverlog) { Debug.Log(string.Format("[CHAT] CLAN [{0}] - {1}: {2}", myClan.tag, player.net.connection.username, message)); ConVar.Server.Log("Log.Chat.txt", string.Format("[CHAT] CLAN [{0}] - {1}: {2}\n", myClan.tag, player.net.connection.username, message)); } }  void cmdChatAllychat(BasePlayer player, string command, string[] args) { if (player == null || args.Length == 0) return; var myClan = findClanByUser(player.UserIDString); if (myClan == null) { PrintChat(player, string.Format(msg("notmember", player.UserIDString))); return; } if (myClan.clanAlliances.Count == 0) { PrintChat(player, string.Format(msg("noactiveally", player.UserIDString))); return; } var message = string.Join(" ", args); if (string.IsNullOrEmpty(message)) return; foreach (var clanAllyName in myClan.clanAlliances) { var clanAlly = findClan(clanAllyName); if (clanAlly == null) continue; clanAlly.AllyBroadcastChat(string.Format(msg("allybroadcastformat"), myClan.tag, myClan.PlayerColor(player.UserIDString), player.net.connection.username, message)); } myClan.AllyBroadcastChat(string.Format(msg("broadcastformat"), myClan.PlayerColor(player.UserIDString), player.net.connection.username, message)); if (ConVar.Chat.serverlog) { Debug.Log(string.Format("[CHAT] ALLY [{0}] - {1}: {2}", myClan.tag, player.net.connection.username, message)); ConVar.Server.Log("Log.Chat.txt", string.Format("[CHAT] ALLY [{0}] - {1}: {2}\n", myClan.tag, player.net.connection.username, message)); } }  void cmdChatClanFF(BasePlayer player, string command, string[] args) { if (!enableFFOPtion || player == null) return; var myClan = findClanByUser(player.UserIDString); if (myClan == null) { PrintChat(player, string.Format(msg("notmember", player.UserIDString))); return; } if (manuallyEnabledBy.Contains(player.userID)) { manuallyEnabledBy.Remove(player.userID); PrintChat(player, string.Format(msg("clanffdisabled", player.UserIDString), colorClanFFOff)); return; } else { manuallyEnabledBy.Add(player.userID); PrintChat(player, string.Format(msg("clanffenabled", player.UserIDString), colorClanFFOn)); return; } }  public bool HasFFEnabled(ulong playerId) => !enableFFOPtion ? false : !manuallyEnabledBy.Contains(playerId) ? false : true;  public void ToggleFF(ulong playerId) { if (manuallyEnabledBy.Contains(playerId)) manuallyEnabledBy.Remove(playerId); else manuallyEnabledBy.Add(playerId); }  public class Clan { public string tag; public string description; public string owner; public string council; public int created; public int updated; [JsonIgnore] public int online; [JsonIgnore] public int total; [JsonIgnore] public int mods; public List<string> moderators = new List<string>(); public List<string> members = new List<string>(); public Dictionary<string, int> invites = new Dictionary<string, int>();  public List<string> clanAlliances = new List<string>(); public List<string> invitedAllies = new List<string>(); public List<string> pendingInvites = new List<string>();  public static Clan Create(string tag, string description, string ownerId) { var clan = new Clan() { tag = tag, description = description, owner = ownerId, created = cc.UnixTimeStampUTC(), updated = cc.UnixTimeStampUTC() }; clan.members.Add(ownerId); return clan; }  public bool IsOwner(string userId) { return userId == owner; }  public bool IsCouncil(string userId) { return userId == council; }  public bool IsModerator(string userId) { return moderators.Contains(userId); }  public bool IsMember(string userId) { return members.Contains(userId); }  public bool IsInvited(string userId) { return invites.ContainsKey(userId); }  public void BroadcastChat(string message) { foreach (var memberId in members) { var player = BasePlayer.Find(memberId); if (player == null) continue; player.ChatMessage(string.Format(cc.broadcastPrefixFormat, cc.broadcastPrefixColor, cc.broadcastPrefix) + $"<color={cc.broadcastMessageColor}>{message}</color>"); } }  public void BroadcastLoc(string messagetype, string arg1 = "", string arg2 = "", string arg3 = "", string arg4 = "", string current = "") { string message = string.Empty; foreach (var memberId in members) { var player = BasePlayer.Find(memberId); if (player == null || player.UserIDString == current) continue; message = string.Format(cc.msg(messagetype, memberId), arg1, arg2, arg3, arg4); player.ChatMessage(string.Format(cc.broadcastPrefixFormat, cc.broadcastPrefixColor, cc.broadcastPrefix) + $"<color={cc.broadcastMessageColor}>{message}</color>"); } }  public void AllyBroadcastChat(string message) { foreach (var memberId in members) { var player = BasePlayer.Find(memberId); if (player == null) continue; player.ChatMessage(string.Format(cc.broadcastPrefixFormat, cc.broadcastPrefixColor, cc.broadcastPrefixAlly) + $"<color={cc.broadcastMessageColor}>{message}</color>"); } }  public void AllyBroadcastLoc(string messagetype, string arg1 = "", string arg2 = "", string arg3 = "", string arg4 = "") { string message = string.Empty; foreach (var memberId in members) { var player = BasePlayer.Find(memberId); if (player == null) continue; message = string.Format(cc.msg(messagetype, memberId), arg1, arg2, arg3, arg4); player.ChatMessage(string.Format(cc.broadcastPrefixFormat, cc.broadcastPrefixColor, cc.broadcastPrefixAlly) + $"<color={cc.broadcastMessageColor}>{message}</color>"); } }  public string ColNam(string Id, string Name) { if (IsOwner(Id)) return $"<color={cc.clanOwnerColor}>{Name}</color>"; else if (IsCouncil(Id) && !IsOwner(Id)) return $"<color={cc.clanCouncilColor}>{Name}</color>"; else if (IsModerator(Id) && !IsOwner(Id)) return $"<color={cc.clanModeratorColor}>{Name}</color>"; else return $"<color={cc.clanMemberColor}>{Name}</color>"; }  public string PlayerLevel(string userID) { if (IsOwner(userID)) return "Owner"; if (IsCouncil(userID)) return "Council"; if (IsModerator(userID)) return "Moderator"; return "Member"; }  public string PlayerColor(string userID) { if (IsOwner(userID)) return cc.clanOwnerColor; if (IsCouncil(userID)) return cc.clanCouncilColor; if (IsModerator(userID)) return cc.clanModeratorColor; return cc.clanMemberColor; }  public IPlayer GetIPlayer(string partialName) { var player = cc.rust.FindPlayerByName(partialName); if (player != null) return cc.covalence.Players.FindPlayer(player.UserIDString); try { var iplayer = cc.covalence.Players.FindPlayer(partialName); if (iplayer is IPlayer) return iplayer; } catch { } var idplayer = cc.covalence.Players.FindPlayer(partialName); if (idplayer != null) return idplayer; return null; }  internal JObject ToJObject() { var obj = new JObject(); obj["tag"] = tag; obj["description"] = description; obj["owner"] = owner; obj["council"] = council; var jmoderators = new JArray(); foreach (var moderator in moderators) jmoderators.Add(moderator); obj["moderators"] = jmoderators; var jmembers = new JArray(); foreach (var member in members) jmembers.Add(member); obj["members"] = jmembers; var jallies = new JArray(); foreach (var ally in clanAlliances) jallies.Add(ally); obj["allies"] = jallies; var jinvallies = new JArray(); foreach (var ally in invitedAllies) jinvallies.Add(ally); obj["invitedallies"] = jinvallies; return obj; }  internal void onCreate() => Interface.CallHook("OnClanCreate", tag);  internal void onUpdate() => Interface.CallHook("OnClanUpdate", tag);  internal void onDestroy() => Interface.CallHook("OnClanDestroy", tag); }  [HookMethod("GetClan")] private JObject GetClan(string tag) { if (tag == null || tag == "") return null; var clan = findClan(tag); if (clan == null) return null; return clan.ToJObject(); }  [HookMethod("GetAllClans")] private JArray GetAllClans() { return new JArray(clans.Keys); }  [HookMethod("GetClanOf")] private string GetClanOf(object player) { if (player == null) throw new ArgumentException("player"); if (player is ulong) player = ((ulong)player).ToString(); else if (player is BasePlayer) player = (player as BasePlayer).userID.ToString(); if (!(player is string)) throw new ArgumentException("player"); var clan = findClanByUser((string)player); if (clan == null) return null; return clan.tag; }  [HookMethod("GetClanMembers")] private List<ulong> GetClanMembers(ulong PlayerID) { List<ulong> Players = new List<ulong>(); var myClan = findClanByUser(PlayerID.ToString()); if (myClan == null) return null; foreach (var it in myClan.members) Players.Add(Convert.ToUInt64(it)); return Players; }  [HookMethod("HasFriend")] private object HasFriend(ulong entOwnerID, ulong PlayerUserID) { var clanOwner = findClanByUser(entOwnerID.ToString()); if (clanOwner == null) return null; var clanFriend = findClanByUser(PlayerUserID.ToString()); if (clanFriend == null) return null; if (clanOwner.tag == clanFriend.tag) return true; return false; }  [HookMethod("IsModerator")] private object IsModerator(ulong PlayerUserID) { var clan = findClanByUser(PlayerUserID.ToString()); if (clan == null) return null; if ((setHomeOwner && clan.IsOwner(PlayerUserID.ToString())) || (setHomeModerator && (clan.IsModerator(PlayerUserID.ToString()) || clan.IsCouncil(PlayerUserID.ToString()))) || setHomeMember) return true; return false; }  private Int32 UnixTimeStampUTC() { Int32 unixTimeStamp; DateTime currentTime = DateTime.Now; DateTime zuluTime = currentTime.ToUniversalTime(); DateTime unixEpoch = new DateTime(1970, 1, 1); unixTimeStamp = (Int32)(zuluTime.Subtract(unixEpoch)).TotalSeconds; return unixTimeStamp; }  private static DateTime UnixTimeStampToDateTime(double unixTimeStamp) { return unixTimeStamp > MaxUnixSeconds ? UnixEpoch.AddMilliseconds(unixTimeStamp) : UnixEpoch.AddSeconds(unixTimeStamp); }  string msg(string key, string id = null) => lang.GetMessage(key, this, id);  void PrintChat(BasePlayer player, string message) { SendReply(player, string.Format(pluginPrefixFormat, pluginPrefixColor, pluginPrefix) + $"<color={colorTextMsg}>" + message + "</color>"); }  [ConsoleCommand("clans")] void cclans(ConsoleSystem.Arg arg) { if (arg != null && arg.Connection != null && arg.Connection.player != null && arg.Connection.authLevel >= 1) { var sb = new StringBuilder(); sb.AppendLine("clans.list (Lists all clans, their owners and their membercount)"); sb.AppendLine("clans.listex (Lists all clans, their owners/members and their onlinestatus)"); sb.AppendLine("clans.show TAG (lists the choosen clan and the members with status)"); sb.AppendLine("clans.msg TAG message without quotes (Sends a clan message)"); if (arg.Connection.authLevel >= authLevelRename) sb.AppendLine("clans.rename OLDTAG NEWTAG (rename's a clan)"); if (arg.Connection.authLevel >= authLevelDelete) sb.AppendLine("clans.delete TAG (delete's a clan)"); if (arg.Connection.authLevel >= authLevelInvite) sb.AppendLine("clans.playerinvite TAG playername (sends clan invitation to a player)"); if (arg.Connection.authLevel >= authLevelKick) sb.AppendLine("clans.playerkick TAG playername (kicks a player from a clan)"); if (arg.Connection.authLevel >= authLevelPromoteDemote) { sb.AppendLine("clans.playerpromote TAG playername (promotes a player)"); sb.AppendLine("clans.playerdemote TAG playername (demotes a player)"); } SendReply(arg, sb.ToString()); } }  [ConsoleCommand("clans.cmds")] void cclansCommands(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 2) return; var sb = new StringBuilder(); sb.AppendLine("\n>> Clans command overview <<\n"); sb.AppendLine("clans.list".PadRight(20) + "| Lists all clans, their owners and their membercount"); sb.AppendLine("clans.listex".PadRight(20) + "| Lists all clans, their owners/members and their onlinestatus"); sb.AppendLine("clans.show".PadRight(20) + "| lists the choosen clan and the members with status"); sb.AppendLine("clans.msg".PadRight(20) + "| message without quotes (Sends a clan message)"); sb.AppendLine("clans.rename".PadRight(20) + "| rename's a clan"); sb.AppendLine("clans.delete".PadRight(20) + "| delete's a clan"); sb.AppendLine("clans.playerinvite".PadRight(20) + "| sends clan invitation to a player"); sb.AppendLine("clans.playerkick".PadRight(20) + "| kicks a player from a clan"); sb.AppendLine("clans.playerpromote".PadRight(20) + "| promotes a player"); sb.AppendLine("clans.playerdemote".PadRight(20) + "| demotes a player"); SendReply(arg, sb.ToString()); }  [ConsoleCommand("clans.list")] void cclansList(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 1) return; TextTable textTable = new TextTable(); textTable.AddColumn("Tag"); textTable.AddColumn("Owner"); textTable.AddColumn("SteamID"); textTable.AddColumn("Count"); textTable.AddColumn("On"); foreach (var iclan in clans) { Clan clan = clans[iclan.Key]; var owner = this.covalence.Players.FindPlayer(clan.owner); if (owner == null) continue; textTable.AddRow(new string[] { clan.tag, owner.Name, clan.owner, clan.total.ToString(), clan.online.ToString() }); } SendReply(arg, "\n>> Current clans <<\n" + textTable.ToString()); }  [ConsoleCommand("clans.listex")] void cclansListEx(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 1) return; TextTable textTable = new TextTable(); textTable.AddColumn("Tag"); textTable.AddColumn("Level"); textTable.AddColumn("Name"); textTable.AddColumn("SteamID"); textTable.AddColumn("Status"); foreach (var iclan in clans) { Clan clan = clans[iclan.Key]; foreach (var memberid in clan.members) { var member = this.covalence.Players.FindPlayer(memberid); if (member == null) continue; textTable.AddRow(new string[] { clan.tag, clan.PlayerLevel(member.Id), member.Name, member.Id.ToString(), (member.IsConnected ? "Online" : "Offline").ToString() }); } textTable.AddRow(new string[] {}); } SendReply(arg, "\n>> Current clans with members <<\n" + textTable.ToString()); }  [ConsoleCommand("clans.show")] void cclansShow(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 1) return; if (arg.Args == null || arg.Args.Length < 1) { SendReply(arg, "Usage: clans.show TAG"); return; } Clan clan; if (!clans.TryGetValue(arg.Args[0], out clan)) if (!clans.TryGetValue(arg.Args[0].ToUpper(), out clan)) { SendReply(arg, string.Format(msg("noclanfound"), arg.Args[0])); return; } var sb = new StringBuilder(); sb.AppendLine($"\n>> Show clan [{clan.tag}] <<"); sb.AppendLine($"Description: {clan.description}"); sb.AppendLine($"Time created: {UnixTimeStampToDateTime(clan.created)}"); sb.AppendLine($"Last updated: {UnixTimeStampToDateTime(clan.updated)}"); sb.AppendLine($"Member count: {clan.total}"); TextTable textTable = new TextTable(); textTable.AddColumn("Level"); textTable.AddColumn("Name"); textTable.AddColumn("SteamID"); textTable.AddColumn("Status"); sb.AppendLine(); foreach (var memberid in clan.members) { var member = this.covalence.Players.FindPlayer(memberid); if (member == null) continue; textTable.AddRow(new string[] { clan.PlayerLevel(member.Id), member.Name, member.Id.ToString(), (member.IsConnected ? "Online" : "Offline").ToString() }); } sb.AppendLine(textTable.ToString()); SendReply(arg, sb.ToString()); }  [ConsoleCommand("clans.msg")] void cclansBroadcast(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 1) return; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "Usage: clans.msg TAG your message without quotes"); return; } Clan clan; if (!clans.TryGetValue(arg.Args[0], out clan)) if (!clans.TryGetValue(arg.Args[0].ToUpper(), out clan)) { SendReply(arg, string.Format(msg("noclanfound"), arg.Args[0])); return; } string BroadcastBy = consoleName; if (arg.Connection != null) { if (arg.Connection.authLevel == 2) BroadcastBy = "(Admin) " + arg.Connection.username; else BroadcastBy = "(Mod) " + arg.Connection.username; } string Msg = ""; for (int i = 1; i < arg.Args.Length; i++) Msg = Msg + " " + arg.Args[i]; clan.BroadcastChat($"<color={clanServerColor}>{BroadcastBy}</color>: {Msg}"); SendReply(arg, $"Broadcast to [{clan.tag}]: {Msg}"); }  [ConsoleCommand("clans.rename")] void cclansRename(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < authLevelRename) return; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "Usage: clans.rename OldTag NewTag"); return; } Clan clan; if (!clans.TryGetValue(arg.Args[0], out clan)) if (!clans.TryGetValue(arg.Args[0].ToUpper(), out clan)) { SendReply(arg, string.Format(msg("noclanfound"), arg.Args[0])); return; } if (tagReExt.IsMatch(arg.Args[1])) { SendReply(arg, string.Format(msg("hintchars"), allowedSpecialChars)); return; } if (arg.Args[1].Length < tagLengthMin || arg.Args[1].Length > tagLengthMax) { SendReply(arg, string.Format(msg("hintlength"), tagLengthMin, tagLengthMax)); return; } if (clans.ContainsKey(arg.Args[1])) { SendReply(arg, string.Format(msg("tagblocked"))); return; } string oldtag = clan.tag; clan.tag = arg.Args[1]; clan.online = 0; clans.Add(clan.tag, clan); clans.Remove(oldtag); setupPlayers(clan.members);  string oldGroup = permGroupPrefix + oldtag; string newGroup = permGroupPrefix + clan.tag; if (permission.GroupExists(oldGroup)) { foreach (var member in clan.members) if (permission.UserHasGroup(member, oldGroup)) permission.RemoveUserGroup(member, oldGroup); permission.RemoveGroup(oldGroup); } if (usePermGroups && !permission.GroupExists(newGroup)) permission.CreateGroup(newGroup, "Clan " + clan.tag, 0); foreach (var member in clan.members) if (usePermGroups && !permission.UserHasGroup(member, newGroup)) permission.AddUserGroup(member, newGroup); string RenamedBy = consoleName; if (arg.Connection != null) RenamedBy = arg.Connection.username; foreach (var ally in clans) { Clan allyClan = clans[ally.Key]; if (allyClan.clanAlliances.Contains(oldtag)) { allyClan.clanAlliances.Remove(oldtag); allyClan.clanAlliances.Add(clan.tag); } if (allyClan.invitedAllies.Contains(oldtag)) { allyClan.invitedAllies.Remove(oldtag); allyClan.invitedAllies.Add(clan.tag); } if (allyClan.pendingInvites.Contains(oldtag)) { allyClan.pendingInvites.Remove(oldtag); allyClan.pendingInvites.Add(clan.tag); } } clan.BroadcastLoc("clanrenamed", $"<color={clanServerColor}>{RenamedBy}</color>", clan.tag); SendReply(arg, string.Format(msg("yourenamed"), oldtag, clan.tag)); clan.onUpdate(); }  [ConsoleCommand("clans.playerinvite")] void cclansPlayerInvite(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < authLevelInvite) return; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "Usage: clans.playerinvite TAG playername"); return; } Clan myClan; Clan check; if (!clans.TryGetValue(arg.Args[0], out check)) { SendReply(arg, string.Format(msg("noclanfound"), arg.Args[0])); return; } else myClan = (Clan)check;  var invPlayer = myClan.GetIPlayer(arg.Args[1]); if (invPlayer == null) { SendReply(arg, string.Format(msg("nosuchplayer"), arg.Args[1])); return; } if (myClan.members.Contains(invPlayer.Id)) { SendReply(arg, string.Format(msg("alreadymember"), invPlayer.Name)); return; } if (myClan.invites.ContainsKey(invPlayer.Id)) { SendReply(arg, string.Format(msg("alreadyinvited"), invPlayer.Name)); return; } if (findClanByUser(invPlayer.Id) != null) { SendReply(arg, string.Format(msg("alreadyinclan"), invPlayer.Name)); return; } myClan.invites.Add(invPlayer.Id, UnixTimeStampUTC()); if (!pendingPlayerInvites.ContainsKey(invPlayer.Id)) pendingPlayerInvites.Add(invPlayer.Id, new List<string>()); pendingPlayerInvites[invPlayer.Id].Add(myClan.tag); if (invPlayer.IsConnected) { var invited = rust.FindPlayerByIdString(invPlayer.Id); if (invited != null) PrintChat(invited, string.Format(msg("claninvite", invPlayer.Id), myClan.tag, myClan.description, colorCmdUsage)); } myClan.updated = UnixTimeStampUTC(); SendReply(arg, $"Invitation for clan '{myClan.tag}' sent to '{invPlayer.Name}'"); }  [ConsoleCommand("clans.playerkick")] void cclansPlayerKick(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < authLevelKick) return; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "Usage: clans.playerkick TAG playername"); return; } Clan myClan; Clan check; if (!clans.TryGetValue(arg.Args[0], out check)) { SendReply(arg, string.Format(msg("noclanfound"), arg.Args[0])); return; } else myClan = (Clan)check; var kickPlayer = myClan.GetIPlayer(arg.Args[1]); if (kickPlayer == null) { SendReply(arg, string.Format(msg("nosuchplayer"), arg.Args[1])); return; } if (!myClan.IsMember(kickPlayer.Id) && !myClan.IsInvited(kickPlayer.Id)) { SendReply(arg, string.Format(msg("notm