[1]); if (promotePlayer == null) { SendReply(arg, string.Format(msg("nosuchplayer"), arg.Args[1])); return; } if (!myClan.IsMember(promotePlayer.Id)) { SendReply(arg, string.Format(msg("notaclanmember"), promotePlayer.Name)); return; } if (enableClanAllies && myClan.IsCouncil(promotePlayer.Id)) { SendReply(arg, string.Format(msg("alreadyacouncil"), promotePlayer.Name)); return; } if (enableClanAllies && myClan.council != null && myClan.IsModerator(promotePlayer.Id)) { SendReply(arg, string.Format(msg("alreadyacouncilset"), promotePlayer.Name)); return; } if (!enableClanAllies && myClan.IsModerator(promotePlayer.Id)) { SendReply(arg, string.Format(msg("alreadyamod"), promotePlayer.Name)); return; } if (!myClan.IsModerator(promotePlayer.Id) && limitModerators >= 0 && myClan.moderators.Count() >= limitModerators) { SendReply(arg, string.Format(msg("maximummods"))); return; } string PromotedBy = consoleName; if (arg.Connection != null) PromotedBy = arg.Connection.username; if (enableClanAllies && myClan.IsModerator(promotePlayer.Id)) { myClan.council = promotePlayer.Id; myClan.moderators.Remove(promotePlayer.Id); myClan.BroadcastLoc("playerpromotedcouncil", $"<color={clanServerColor}>{PromotedBy}</color>", myClan.ColNam(promotePlayer.Id, promotePlayer.Name)); } else { myClan.moderators.Add(promotePlayer.Id); myClan.BroadcastLoc("playerpromoted", $"<color={clanServerColor}>{PromotedBy}</color>", myClan.ColNam(promotePlayer.Id, promotePlayer.Name)); } myClan.updated = UnixTimeStampUTC(); myClan.onUpdate(); SendReply(arg, $"You promoted '{promotePlayer.Name}' to a {myClan.PlayerLevel(promotePlayer.Id.ToString())}"); }  [ConsoleCommand("clans.playerdemote")] void cclansPlayerDemote(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < authLevelPromoteDemote) return; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "Usage: clans.playerdemote TAG playername"); return; } Clan myClan; Clan check; if (!clans.TryGetValue(arg.Args[0], out c