landeleted", $"<color={clanServerColor}>{DeletedBy}</color>"); clans.Remove(arg.Args[0]); foreach (var member in clan.members) clanCache.Remove(member); setupPlayers(clan.members); string permGroup = permGroupPrefix + clan.tag; if (permission.GroupExists(permGroup)) { foreach (var member in clan.members) if (permission.UserHasGroup(member, permGroup)) permission.RemoveUserGroup(member, permGroup); permission.RemoveGroup(permGroup); } foreach (var ally in clans) { Clan allyClan = clans[ally.Key]; allyClan.clanAlliances.Remove(arg.Args[0]); allyClan.invitedAllies.Remove(arg.Args[0]); allyClan.pendingInvites.Remove(arg.Args[0]); } SendReply(arg, string.Format(msg("youdeleted"), clan.tag)); clan.onDestroy(); Interface.Oxide.CallHook("OnClanDisbanded", clan.members); AllyRemovalCheck(); }  bool FilterText(string tag) { foreach (string bannedword in wordFilter) if (TranslateLeet(tag).ToLower().Contains(bannedword.ToLower())) return true; return false; }  string TranslateLeet(string original) { string translated = original; Dictionary<string, string> leetTable = new Dictionary<string, string> { { "}{", "h" }, { "|-|", "h" }, { "]-[", "h" }, { "/-/", "h" }, { "|{", "k" }, { "/\\/\\", "m" }, { "|\\|", "n" }, { "/\\/", "n" }, { "()", "o" }, { "[]", "o" }, { "vv", "w" }, { "\\/\\/", "w" }, { "><", "x" }, { "2", "z" }, { "4", "a" }, { "@", "a" }, { "8", "b" }, { "ß", "b" }, { "(", "c" }, { "<", "c" }, { "{", "c" }, { "3", "e" }, { "€", "e" }, { "6", "g" }, { "9", "g" }, { "&", "g" }, { "#", "h" }, { "$", "s" }, { "7", "t" }, { "|", "l" }, { "1", "i" }, { "!", "i" }, { "0", "o" }, }; foreach (var leet in leetTable) translated = translated.Replace(leet.Key, leet.Value); return translated; }  [HookMethod("EnableBypass")] void EnableBypass(object userId) { if (!enableFFOPtion || userId == null) return; if (userId is string) userId = Convert.ToUInt64((string)userId); bypass.Add((ulong)userId); }  [HookMethod("DisableBypass")] void DisableBypass(object userId) { if (!enableFFOPtion |